@@ -0,0 +1,37 @@
+import type { SQSBatchResponse, SQSEvent } from 'aws-lambda';
+import type { OrderLineRow } from '../../../orders/src/internal/repository/rows';
+import { lineTotalMinor } from '../../../orders/src/internal/pricing/lineTotal';
+import { createInvoice } from '../invoices/createInvoice';
+
+interface ShipmentCreated {
+  orderId: string;
+  shipmentId: string;
+  customerId: string;
+  currency: string;
+  lines: OrderLineRow[];
+}
+
+export async function handler(event: SQSEvent): Promise<SQSBatchResponse> {
+  const batchItemFailures: SQSBatchResponse['batchItemFailures'] = [];
+  for (const record of event.Records) {
+    try {
+      const shipped = JSON.parse(record.body) as ShipmentCreated;
+      await createInvoice({
+        orderId: shipped.orderId,
+        shipmentId: shipped.shipmentId,
+        customerId: shipped.customerId,
+        currency: shipped.currency,
+        lines: shipped.lines.map((line) => ({
+          sku: line.sku,
+          quantity: line.quantity,
+          amountMinor: lineTotalMinor(line),
+        })),
+        idempotencyKey: `${shipped.shipmentId}-invoice`,
+      });
+    } catch (err) {
+      console.error('invoice failed', { messageId: record.messageId, err });
+      batchItemFailures.push({ itemIdentifier: record.messageId });
+    }
+  }
+  return { batchItemFailures };
+}
