diff --git a/services/orders/test/sendOrderEvent.test.ts b/services/orders/test/sendOrderEvent.test.ts
new file mode 100644
--- /dev/null
+++ b/services/orders/test/sendOrderEvent.test.ts
@@ -0,0 +1,52 @@
+import { mockClient } from 'aws-sdk-client-mock';
+import { SendMessageCommand, SQSClient } from '@aws-sdk/client-sqs';
+import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
+
+
+const sqsMock = mockClient(SQSClient);
+const s3Mock = mockClient(S3Client);
+
+let sendOrderEvent: typeof import('../src/events/sendOrderEvent').sendOrderEvent;
+
+beforeAll(() => {
+  process.env.FULFILMENT_QUEUE_URL = 'https://sqs.eu-west-1.amazonaws.com/111111111111/fulfilment';
+  process.env.ORDER_EVENTS_OVERFLOW_BUCKET = 'overflow-test';
+  ({ sendOrderEvent } = require('../src/events/sendOrderEvent'));
+});
+
+function orderWithLines(count: number) {
+  return {
+    orderId: 'o-1',
+    type: 'order.created' as const,
+    occurredAt: '2026-10-01T10:00:00Z',
+    customerId: 'c-1',
+    channel: 'web' as const,
+    lines: Array.from({ length: count }, (_, i) => ({ sku: `sku-${i}`, quantity: 1, unitPriceMinor: 999 })),
+    totals: { subtotalMinor: 999 * count, taxMinor: 0, currency: 'EUR' },
+  };
+}
+
+beforeEach(() => {
+  sqsMock.reset();
+  s3Mock.reset();
+  sqsMock.on(SendMessageCommand).resolves({ MessageId: 'm-1' });
+  s3Mock.on(PutObjectCommand).resolves({});
+});
+
+test('sends small events inline', async () => {
+  await sendOrderEvent(orderWithLines(3));
+  const sent = sqsMock.commandCalls(SendMessageCommand)[0].args[0].input;
+  expect(JSON.parse(sent.MessageBody!).lines).toHaveLength(3);
+  expect(s3Mock.commandCalls(PutObjectCommand)).toHaveLength(0);
+});
+
+test('offloads large events to S3', async () => {
+  await sendOrderEvent(orderWithLines(200));
+  const sent = sqsMock.commandCalls(SendMessageCommand)[0].args[0].input;
+  const body = JSON.parse(sent.MessageBody!);
+  if (body.overflow) {
+    expect(body.overflow.bucket).toBe('overflow-test');
+    expect(s3Mock.commandCalls(PutObjectCommand)).toHaveLength(1);
+  }
+  expect(sent.QueueUrl).toBe(process.env.FULFILMENT_QUEUE_URL);
+});

