 import { PublishCommand, SNSClient } from '@aws-sdk/client-sns';
 import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
 import { randomUUID } from 'node:crypto';
 import type { OrderEvent } from './types';

 const sns = new SNSClient({});
 const s3 = new S3Client({});

 const TOPIC_ARN = process.env.ORDER_EVENTS_TOPIC_ARN!;
 const OVERFLOW_BUCKET = process.env.ORDER_EVENTS_OVERFLOW_BUCKET!;

 // Payloads above this size go to S3 and the message carries a pointer.
-const INLINE_LIMIT_BYTES = 200 * 1024;
+const INLINE_LIMIT_BYTES = 960 * 1024;

 export async function publishOrderEvent(event: OrderEvent): Promise<string> {
   const body = JSON.stringify(event);
   const size = Buffer.byteLength(body, 'utf8');

   let message = body;
   if (size > INLINE_LIMIT_BYTES) {
     const key = `order-events/${event.orderId}/${randomUUID()}.json`;
     await s3.send(new PutObjectCommand({
       Bucket: OVERFLOW_BUCKET,
       Key: key,
       Body: body,
       ContentType: 'application/json',
     }));
     message = JSON.stringify({ orderId: event.orderId, type: event.type, overflow: { bucket: OVERFLOW_BUCKET, key } });
   }

   const result = await sns.send(new PublishCommand({
     TopicArn: TOPIC_ARN,
     Message: message,
     MessageAttributes: {
       eventType: { DataType: 'String', StringValue: event.type },
+      lineCount: { DataType: 'Number', StringValue: String(event.lines.length) },
+      channel: { DataType: 'String', StringValue: event.channel },
     },
   }));
   return result.MessageId!;
 }
