+import os
+
+import requests
+
+PAYMENTS_API_URL = os.environ['PAYMENTS_API_URL']
+session = requests.Session()
+
+
+class PaymentProviderUnavailable(Exception):
+    pass
+
+
+class PaymentDeclined(Exception):
+    pass
+
+
+def charge_handler(event, context):
+    response = session.post(
+        f'{PAYMENTS_API_URL}/charges',
+        headers={'Idempotency-Key': event['idempotencyKey']},
+        json={
+            'order_id': event['orderId'],
+            'payment_method_id': event['paymentMethodId'],
+            'amount_minor': event['amountMinor'],
+            'currency': event['currency'],
+            'capture': True,
+        },
+        timeout=20,
+    )
+    if response.status_code >= 500:
+        raise PaymentProviderUnavailable(response.text[:200])
+    if response.status_code == 402:
+        raise PaymentDeclined(response.json().get('decline_code', 'unknown'))
+    response.raise_for_status()
+    return {'chargeId': response.json()['id']}

